92	  // `push`/`pr` are the pre-rename aliases for `auto`/`review` — accepted permanently
93	  // (the maintenance-delivery-rename migration rewrites the stored value, but the
94	  // tolerance outlives the record, so retiring it strands nothing).
95	  const delivery = rawDelivery === 'push' || rawDelivery === 'auto' ? 'auto-merge' : rawDelivery === 'pr' ? 'review' : rawDelivery;
96	
97	  if (delivery !== 'auto-merge' && delivery !== 'review') {
98	    await io.openIssue(
99	      fullName,
100	      'Claudinite maintenance: unrecognized delivery preference',
101	      `\`.claudinite-checks.json\` sets \`maintenance.delivery: "${rawDelivery}"\`, which is neither \`auto-merge\` nor \`review\`. `
102	        + 'Migrations were not applied this run. Set it to `auto` or `review`.',
103	    );
104	    return { ids: [], note: `${fullName}: unrecognized delivery "${rawDelivery}" — opened an issue, applied nothing` };
105	  }
106	
107	  // Both deliveries land on the stable `claudinite/maintenance` branch and its one
108	  // PR — never a direct commit to the default branch. `review` leaves that PR for the
109	  // owner; `auto` arms GitHub auto-merge on it, so it lands automatically
110	  // once the repo's checks pass (the run never blocks on CI). How strictly "once
111	  // checks pass" holds depends on the repo requiring its checks (branch protection);
112	  // with none required, GitHub lands the PR as soon as it's mergeable.
113	  const notes = [];
114	
115	  // Desired end-state is ALWAYS computed against the default branch — the truth
116	  // being migrated — never the maintenance branch's own copy (#332).
117	  const staged = await stageMemberWrites(io, fullName, defaultBranch, migrations);
118	  if (!staged) return { ids: [], note: undefined };
119	
120	  await io.ensureBranch(fullName, MAINT_BRANCH, defaultBranch);
121	  // Refresh the branch from base before the diff below and the eventual merge, so a
122	  // long-open PR isn't merged stale-based (#332). A conflict is the owner's to see,
123	  // never resolved here.

